const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  OWNER_EMAIL: s.owner_email,
  OWNER_PHONE: s.owner_phone_e164,
  TWILIO_FROM_NUMBER: s.twilio_from_number,
  EMAIL_ALERTS_ENABLED: s.email_alerts_enabled,
  SMS_ALERTS_ENABLED: s.sms_reports_enabled,
  DEFAULT_TIMEZONE: s.timezone,
  WINDOW_DAYS: s.weekly_report_window_days,
  TOP_SOURCES_COUNT: s.weekly_report_top_sources_count
};

const now = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE);
const weekAgo = now.minus({ days: CONFIG.WINDOW_DAYS });
const weekAgoStr = weekAgo.toFormat('yyyy-MM-dd');
const todayStr = now.toFormat('yyyy-MM-dd');

const leads = $input.all().map(i => i.json);

let newThisWeek = 0;
let bookedThisWeek = 0;
let staleThisWeek = 0;
const sourceCounts = {};

for (const lead of leads) {
  const created = String(lead['Date Created'] || '').slice(0, 10);
  if (created >= weekAgoStr && created <= todayStr) {
    newThisWeek++;
    const source = (lead['Source'] || '').trim() || 'Unknown';
    sourceCounts[source] = (sourceCounts[source] || 0) + 1;
  }

  const status = (lead['Status'] || '').trim();
  const lastContact = String(lead['Last Contact'] || '').slice(0, 10);
  const inWindow = lastContact >= weekAgoStr && lastContact <= todayStr;
  if (status === 'Booked' && inWindow) bookedThisWeek++;
  if (status === 'Stale' && inWindow) staleThisWeek++;
}

const bookingRatio = newThisWeek > 0 ? Math.round((bookedThisWeek / newThisWeek) * 100) : 0;
const topSources = Object.entries(sourceCounts).sort((a, b) => b[1] - a[1]).slice(0, CONFIG.TOP_SOURCES_COUNT);
const sourceText = topSources.length ? topSources.map(([s, c]) => s + ' (' + c + ')').join(', ') : 'n/a';

const windowLabel = weekAgo.toFormat('MMM d') + ' - ' + now.toFormat('MMM d, yyyy');

let smsMessage = 'Weekly Report - ' + CONFIG.COMPANY_NAME + ' (' + windowLabel + ')\n';
smsMessage += 'New leads: ' + newThisWeek + '\n';
smsMessage += 'Booked: ' + bookedThisWeek + ' | Stale: ' + staleThisWeek + ' | Bookings/New ratio: ' + bookingRatio + '%\n';
smsMessage += 'Top sources: ' + sourceText;

const emailSubject = CONFIG.COMPANY_NAME + ' - Weekly Pipeline Report (' + windowLabel + ')';

const metricRows = [
  ['New Leads', newThisWeek],
  ['Booked', bookedThisWeek],
  ['Stale', staleThisWeek],
  ['Bookings / New Ratio', bookingRatio + '%'],
  ['Top Sources', sourceText]
].map(([label, value]) =>
  '<tr><td style="padding:6px 12px 6px 0;font-weight:bold;color:#374151;white-space:nowrap;">' + label + '</td><td style="padding:6px 0;color:#111827;">' + value + '</td></tr>'
).join('');

const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;">' +
  '<h2 style="color:#111827;border-bottom:2px solid #e5e7eb;padding-bottom:8px;">Weekly Pipeline Report</h2>' +
  '<p style="color:#6b7280;margin-top:0;">' + windowLabel + '</p>' +
  '<table style="width:100%;border-collapse:collapse;margin-top:12px;">' + metricRows + '</table>' +
  '<p style="color:#6b7280;font-size:12px;margin-top:24px;">Sent automatically by ' + CONFIG.COMPANY_NAME + '.</p>' +
  '</div>';

return [{ json: {
  emailEnabled: CONFIG.EMAIL_ALERTS_ENABLED,
  smsEnabled: CONFIG.SMS_ALERTS_ENABLED,
  ownerEmail: CONFIG.OWNER_EMAIL,
  ownerPhone: CONFIG.OWNER_PHONE,
  twilioFrom: CONFIG.TWILIO_FROM_NUMBER,
  emailSubject,
  emailHtml,
  smsMessage,
  windowStart: weekAgoStr,
  windowEnd: todayStr,
  newThisWeek,
  bookedThisWeek,
  staleThisWeek,
  bookingRatio,
  sourceCounts
} }];
